const content = $json["Original Content"] || "";

const linkedinPost = content;

const xPost =
  content.length <= 280
    ? content
    : content.substring(0, 277) + "...";

const facebookPost = content;

return [
  {
    json: {
      campaign: $json["Campaign"],
      contentId: $json["Content ID"],
      rowNumber: $json.row_number,

      linkedinPost,
      xPost,
      facebookPost
    }
  }
];

return [
  {
    json: {
      contentId: $json.contentId,
      rowNumber: $json.rowNumber,
      campaign: $json.campaign,
      platform: "LinkedIn",
      status: "SIMULATED_SUCCESS",
      postText: $json.linkedinPost,
      distributedAt: new Date().toISOString(),
      message: "LinkedIn post successfully simulated"
    }
  }
];

return [
  {
    json: {
      contentId: $json.contentId,
      rowNumber: $json.rowNumber,
      campaign: $json.campaign,
      platform: "X",
      status: "SIMULATED_SUCCESS",
      postText: $json.xPost,
      distributedAt: new Date().toISOString(),
      message: "X post successfully simulated"
    }
  }
];

return [
  {
    json: {
      contentId: $json.contentId,
      rowNumber: $json.rowNumber,
      campaign: $json.campaign,
      platform: "Facebook",
      status: "SIMULATED_SUCCESS",
      postText: $json.facebookPost,
      distributedAt: new Date().toISOString(),
      message: "Facebook post successfully simulated"
    }
  }
];

return [
  {
    json: {
      contentId: $json.contentId,
      rowNumber: $json.rowNumber,
      campaign: $json.campaign,
      platform: $json.platform,
      status: $json.status,
      postText: $json.postText,
      distributedAt: $json.distributedAt,
      message: $json.message,
      loggedAt: new Date().toISOString()
    }
  }
];
